import numpy as np
import time
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    if h.size < 1:
        return 0.0
    if not np.all(np.isfinite(h)) or np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    if L.size < 1:
        return -1.0
    m = L.max()
    if m <= 0:
        return -1.0
    # ||f*f||_2^2 = sum_j (L_j^2 + L_j L_{j+1} + L_{j+1}^2)/3 with L_0 = L_{N+1} = 0
    Lp = np.concatenate(([0.0], L, [0.0]))
    a = Lp[:-1]
    b = Lp[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = s * s
    return l2sq / (l1 * m)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.9

    N = 4001
    x = np.linspace(0.0, 1.0, N)
    d = np.abs(x - 0.5)

    def make(s, p):
        if s <= 0 or p <= 0:
            return None
        return np.exp(-((d / s) ** p))

    best_h = None
    best_R = -1.0

    # Keep start as a fallback candidate.
    if start is not None:
        hs = np.asarray(start, dtype=float)
        rs = _R(hs)
        if rs > best_R:
            best_R = rs
            best_h = hs.copy()

    ps = [1.0, 1.5, 2.0, 2.5, 3.0, 4.0, 6.0]
    ss = np.logspace(np.log10(0.03), np.log10(0.5), 25)

    for p in ps:
        if time.process_time() > deadline:
            break
        for s in ss:
            if time.process_time() > deadline:
                break
            h = make(s, p)
            if h is None:
                continue
            r = _R(h)
            if r > best_R:
                best_R = r
                best_h = h

    if best_h is None:
        best_h = np.ones(50)
        best_R = _R(best_h)

    # Refine with Nelder-Mead in (log s, log p).
    # Recover a starting guess from best_h by fitting s,p roughly.
    # Use the coarse grid best parameters if tracked; otherwise derive from best_h.
    # Simpler: search around plausible values, seeded by best coarse point.
    # We'll re-run a small local scan to find seed params matching best_h.
    # To avoid overhead, just optimize from a few seeds.
    def negR(z):
        s = np.exp(z[0])
        p = np.exp(z[1])
        if s > 2.0 or p > 20.0 or s < 1e-4 or p < 0.1:
            return 1e6
        h = make(s, p)
        return -_R(h)

    # Find best coarse params again (cheap) to seed.
    seeds = []
    best_seed = None
    best_seed_r = -1.0
    for p in ps:
        for s in ss:
            h = make(s, p)
            r = _R(h)
            if r > best_seed_r:
                best_seed_r = r
                best_seed = (np.log(s), np.log(p))
    if best_seed is not None:
        seeds.append(best_seed)
    seeds.append((np.log(0.15), np.log(2.0)))
    seeds.append((np.log(0.12), np.log(2.5)))

    for seed in seeds:
        if time.process_time() > deadline:
            break
        try:
            res = minimize(negR, np.array(seed), method='Nelder-Mead',
                           options={'maxiter': 2000, 'xatol': 1e-6, 'fatol': 1e-9})
            z = res.x
            s = np.exp(z[0])
            p = np.exp(z[1])
            h = make(s, p)
            if h is not None:
                r = _R(h)
                if r > best_R:
                    best_R = r
                    best_h = h
        except Exception:
            pass

    # Extra: local fine scan around best if time remains.
    if time.process_time() < deadline and best_h is not None:
        # Try a few fine s around 0.1-0.2 with p near 2
        for p in np.linspace(1.5, 3.5, 9):
            if time.process_time() > deadline:
                break
            for s in np.linspace(0.08, 0.25, 18):
                if time.process_time() > deadline:
                    break
                h = make(s, p)
                r = _R(h)
                if r > best_R:
                    best_R = r
                    best_h = h

    return np.asarray(best_h, dtype=float)
